  ctx.save(); ctx.translate(-10, -6); ctx.rotate(-0.25 - flap * 0.8); ctx.beginPath(); ctx.ellipse(-12, 0, 52, 24, 0.1, 0, 6.283); shape(ctx, MEES_B, '#3E5A6E', 2); ctx.restore();
